  // Filter: active is true AND age >= 30
  const filtered = records.filter(r => r.active === true && r.age >= 30);

  // Sort by name ascending
  filtered.sort((a, b) => a.name.localeCompare(b.name));

  // Output to stdout
  console.log(JSON.stringify(filtered));
}

main();
