		if len(row) < 4 {
			// Skip malformed rows
			continue
		}

		name := row[0]
		email := row[2]

		age, err := strconv.Atoi(row[1])
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error converting age for row %d: %v\n", i, err)
			os.Exit(1)
		}

		score, err := strconv.ParseFloat(row[3], 64)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error converting score for row %d: %v\n", i, err)
			os.Exit(1)
		}

