	// Define test cases: {description, price, quantity, expectedResult}
	tests := []struct {
		description string
		price       float64
		quantity    int
		expected    float64
	}{
		{
			description: "Quantity 9 (No discount)",
			price:       10.0,
			quantity:    9,
			expected:    10.0 * 9.0, // 90.0
		},
		{
			description: "Quantity 10 (10% discount boundary)",
			price:       10.0,
			quantity:    10,
