    return;
}

var text = File.ReadAllText(filePath);
var frequencyMap = new Dictionary<string, int>();

// Split by non-letter characters, filter out empty strings, convert to lowercase
var words = text
    .Where(char.IsLetter)
    .ToList()
    .Aggregate(new List<string>(), (list, ch) => 
