    obj["Name"] = node.AsObject()["Name"];
    obj["Age"] = node.AsObject()["Age"];
    obj["Email"] = node.AsObject()["Email"];
    obj["Score"] = node.AsObject()["Score"];
    finalArray.Add(obj);
}

